// library-bundle.d.ts — the shape of the build-injected library bundle.
// The physical module is generated by scripts/build.mjs's esbuild
// plugin from SST_LIBRARY_PATH (the declared instrument library); this
// declaration is what `tsc` typechecks against.

declare module 'sst-library-bundle' {
  export interface LibraryBundleModule {
    /** package.sst.yaml text (the instance's manifest). */
    instanceManifestYaml: string
    /** coefficients.yaml text. */
    coefficientsYaml: string
    /** The resolved sample's YAML text (prefer `fresh`). */
    sampleYaml?: string | undefined
    /** The requested sample ref (bare name). */
    sampleRef?: string | undefined
    /** The kind's world-kind.sdl.graphql text. */
    worldKindSdl: string
    /** The kind's world-kind.yaml text. */
    worldKindYaml: string
    /** The kind's handlers module's `handlers` export. */
    handlers: Record<string, (ctx: unknown, args: Record<string, unknown>) => void>
    /** The baked twin contract artifact (twin/<kind>.twin.json). */
    twinContractJson: unknown
    /** The kind's mpe.yaml text. */
    mpeYaml?: string | undefined
    /** The kind's physics-chain.yaml text. */
    physicsChainYaml?: string | undefined
    /** The imported behavior.js module namespace. */
    behavior: unknown
  }
  export const libraryBundle: LibraryBundleModule
}
